export const DEFAULT_ZOROF_CATEGORY: ZorofCategory = 'PLATTERS';

export function zorofCategoryFromSlug(slug: string | null): ZorofCategory {
  const match = (Object.keys(ZOROF_CATEGORIES) as ZorofCategory[]).find(
    (c) => ZOROF_CATEGORIES[c].slug === slug,
  );
  return match ?? DEFAULT_ZOROF_CATEGORY;
}

function product(
  id: string,
  category: ZorofCategory,
  de: string,
  fa: string,
  files: string[],
  sizes: string[] = [],
): ZorofProduct {
  const images = img(id, files);
  return { id, category, name: { fa, de }, sizes, images, coverImage: images[0] };
}

